import { checkoutTotal } from "../src/checkout.js";

test("无券：商品金额 + 运费", () => {
  assert.equal(checkoutTotal([{ unitPrice: 1000, qty: 2 }], 0), 2600);
});

test("已包邮：只付商品金额", () => {
  assert.equal(checkoutTotal([{ unitPrice: 6000, qty: 1 }], 0), 6000);
});

